input.content:
import { IngestPipeline } from "@514labs/moose-lib";

export interface UserActivity {
  eventId: string;
  eventTs: Date;
  userId: string;
  action: string;
  durationMs: number;
}

export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
  table: {
    orderByFields: ["userId", "eventTs", "action"] // Optimized for user-centric queries and date ranges
  },
  stream: true,
  ingestApi: true,
});

